routes.path_expression:
`/folders/children${query({
            club_id: clubId,
            club_department_id: opts.department,
            parent_id: nullableFolder(opts.parent),
            include_deleted: opts.includeDeleted,
          })}`

`/votes/${requiredId(id, action, "Entscheidungs-ID")}/offline-tally/${requiredOption(opts, action)}${query({
        count: requiredInteger(opts.count, action, "--count"),
        increment: opts.increment ? true : undefined,
      })}`

`/resolutions/${query({
        club_id: clubId,
        department_id: opts.department,
        category: opts.category,
        valid_only: opts.includeExpired ? false : undefined,
      })}`

`/club-sponsorship-products/${qs({
              club_id: clubId,
              club_department_id: opts.departmentId,
              active_only: opts.includeInactive ? false : true,
            })}`

`/sponsor-member-assignments/${qs({
              club_id: clubId,
              club_department_id: opts.departmentId,
              advertiser_id: opts.sponsor ?? id,
              member_id: opts.member,
            })}`
